import { GhostButton } from "@/core/components/primitives/parks-button/parks-button";
import { useTranslation } from "react-i18next";
import styles from "./back-button.module.less";

type Props = {
  onClick: () => void;
  labelOverride?: string;
};

export const BackButton = ({ onClick, labelOverride }: Props) => {
  const { t } = useTranslation();
  return (
    <GhostButton
      iconLeftNew="chevron-left"
      label={labelOverride ?? t("back")}
      className={styles.backButton}
      onClick={onClick}
    />
  );
};
